function read(p){return JSON.parse(fs.readFileSync(path.join(ROOT,p),'utf8'));}
function write(p,v){const q=path.join(ROOT,p);fs.mkdirSync(path.dirname(q),{recursive:true});fs.writeFileSync(q,typeof v==='string'?v:JSON.stringify(v,null,2)+'\n');}
function deepClone(v){return JSON.parse(JSON.stringify(v));}
function replaceDeep(v){
  if(typeof v==='string') return v.replaceAll('subkultur_produksjonsledelse',ROLE).replaceAll('produksjonsbok_kjoreplan_bemanning_sikkerhet_og_avvikslogg',PERSIST);
  if(Array.isArray(v)) return v.map(replaceDeep);
  if(v&&typeof v==='object') return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,replaceDeep(x)]));
  return v;
}

