      {id:'B',label:`${d.competency}: skjult programgjeld ${d.id}`,reply:mkText(d.bad,'Jeg lar sosialt eller tidsmessig press styre nå og rydder kriterier, mandat, kostnad, avtale eller forbehold senere dersom noen spør.',190),effect:-1,tags:['mandatglidning','programgjeld','risiko'],feedback:mkText(d.bad,'Det kan bevare tempo eller sosial ro i øyeblikket, men gjør det uklart hva som faktisk var lovet, godkjent, honorert eller publiserbart og flytter kostnad og tillitsrisiko til artister, partnere, økonomi, produksjon eller publikum.',270),effects:{stats:{status:1,quality:-2,trust:-2,risk:3}}}
